function validate([clips, time]) {
  if (!Number.isInteger(time) || time < 1 || time > 100) return 'time must be between 1 and 100.';
  if (!Array.isArray(clips) || clips.length < 1 || clips.length > 100) return 'clips needs 1 to 100 entries.';
  for (const clip of clips) {
    if (!Array.isArray(clip) || clip.length !== 2) return 'Each clip is a pair [start, end].';
    const [start, end] = clip;
    if (!Number.isInteger(start) || !Number.isInteger(end)) return 'Clip bounds must be whole numbers.';
    if (start < 0 || end > 100 || start > end) return 'Each clip needs 0 <= start <= end <= 100.';
  }
  return null;
}

