function videoStitching(clips, time) {
  const reach = new Array(time).fill(0);
  for (const [start, end] of clips) {
    if (start < time) {
      reach[start] = Math.max(reach[start], end);
    }
  }
  let count = 0;
  let covered = 0;
  let farthest = 0;
  for (let t = 0; t < time; t++) {
    farthest = Math.max(farthest, reach[t]);
    if (t === covered) {
      if (farthest <= t) {
        return -1;
      }
      count++;
      covered = farthest;
    }
  }
  return count;
}

