function videoStitching(clips, time) {
  // need[i] = fewest clips covering [0, i]; the clip that covers second i starts at some s < i.
  const need = Array(time + 1).fill(Infinity);
  need[0] = 0;
  for (let i = 1; i <= time; i++) {
    for (const [s, e] of clips) {
      if (s < i && i <= e) need[i] = Math.min(need[i], need[s] + 1);
    }
  }
  return need[time] === Infinity ? -1 : need[time];
}

