function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const time = pick(60, 100);
    const longest = pick(3, 40);
    const clips = Array.from({ length: 100 }, () => {
      const start = pick(0, 100);
      return [start, Math.min(100, start + pick(0, longest))];
    });
    return [clips, time];
  }
  const time = pick(1, 10);
  const n = pick(1, 9);
  const clips = Array.from({ length: n }, () => {
    const start = rand() < 0.3 ? 0 : pick(0, time);
    const length = rand() < 0.1 ? 0 : pick(1, Math.ceil(time / 2) + 1);
    return [start, start + length];
  });
  return [clips, time];
}
